		connectInstance(bridge, edge, "edge", [tab({ tabId: 1, title: "Edge tab", url: "https://edge.example/" })]);
		// Edge reconnects without its tab: its own tab goes, Chrome's tab stays.
		bridge.extClosed(edge);
