describe("RelayBridge orphan reaper close (OMP.closeOwnedTarget)", () => {
	function helloWithOwned(
		bridge: RelayBridge,
		socket: FakeExtSocket,
		tabs: TabSnapshot[],
		ownedTabIds: number[],
	): void {
		bridge.extConnected(socket);
		bridge.extMessage(
			socket,
			JSON.stringify({
				t: "hello",
				userAgent: "test",
				browserVersion: "Chrome/151.0.0.0",
				discardedTabsProtocol: 1,
				tabs,
				attachedTabIds: [],
				ownedTabIds,
			}),
		);
	}

	function reap(bridge: RelayBridge, cdp: FakeCdpSocket, connId: number, tabId: number): number {
		const id = ++msgSeq;
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id, method: "OMP.closeOwnedTarget", params: { targetId: `PAGE${ANON}.${tabId}` } }),
		);
		return id;
	}

	it("closes only omp-created tabs nobody drives; user tabs and live-driven tabs are reported stale", async () => {
		const bridge = new RelayBridge({});
		const ext = new FakeExtSocket();
		helloWithOwned(bridge, ext, [tab({ tabId: 1 }), tab({ tabId: 2 }), tab({ tabId: 3 })], [2, 3]);
		// A live session still drives created tab 3.
		const live = new FakeCdpSocket();
		await claimTab(bridge, ext, live, bridge.cdpConnected(live), 3);

		const reaper = new FakeCdpSocket();
		const reaperConn = bridge.cdpConnected(reaper);
		const userTab = reap(bridge, reaper, reaperConn, 1);
		const drivenTab = reap(bridge, reaper, reaperConn, 3);
		const orphan = reap(bridge, reaper, reaperConn, 2);
		await flush();
		expect(ext.rpcs("removeTab").map(rpc => rpc.tabId)).toEqual([2]);
		ack(bridge, ext, "removeTab");
		await flush();

		const resultOf = (id: number) => reaper.messages.find(message => message.id === id)?.result;
		expect(resultOf(userTab)).toEqual({ closed: false });
		expect(resultOf(drivenTab)).toEqual({ closed: false });
		expect(resultOf(orphan)).toEqual({ closed: true });
	});

	it("errors (record retained) while the target's browser is disconnected", async () => {
		const bridge = new RelayBridge({});
		const ext = new FakeExtSocket();
		helloWithOwned(bridge, ext, [tab({ tabId: 2 })], [2]);
		bridge.extClosed(ext);

		const reaper = new FakeCdpSocket();
		const id = reap(bridge, reaper, bridge.cdpConnected(reaper), 2);
		await flush();
		const reply = reaper.messages.find(message => message.id === id);
		expect(reply && "error" in reply).toBe(true);
		expect(ext.rpcs("removeTab")).toEqual([]);
	});

	it("keeps createTarget ownership across a legacy hello without ownedTabIds", async () => {
		const bridge = new RelayBridge({});
		const ext = new FakeExtSocket();
		connect(bridge, ext, []);
		const creator = new FakeCdpSocket();
		const creatorConn = bridge.cdpConnected(creator);
		bridge.cdpMessage(creatorConn, JSON.stringify({ id: ++msgSeq, method: "Target.createTarget" }));
		ack(bridge, ext, "createTab", { tab: tab({ tabId: 9 }) });
		await flush();
		bridge.cdpClosed(creatorConn);

		// Service-worker restart on an extension build that does not report ownership.
		const legacy = new FakeExtSocket();
		connect(bridge, legacy, [tab({ tabId: 9 })]);
		const reaper = new FakeCdpSocket();
		const reaperConn = bridge.cdpConnected(reaper);
		const id = reap(bridge, reaper, reaperConn, 9);
		await flush();
		expect(legacy.rpcs("removeTab").map(rpc => rpc.tabId)).toEqual([9]);
		ack(bridge, legacy, "removeTab");
		await flush();
		expect(reaper.messages.find(message => message.id === id)?.result).toEqual({ closed: true });
	});

	describe("durable orphan reaper integration", () => {
		interface ReaperFixture {
			bridge: RelayBridge;
			ownershipFile: string;
			targetId: string;
			reap(): Promise<number>;
		}

		async function withOrphanRecord(run: (fixture: ReaperFixture) => Promise<void>): Promise<void> {
			const runtimeDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-relay-orphan-"));
			const relay = startRelayServer({ port: await findFreeCdpPort(), group: false });
			try {
				// Reap a real exited process so the production PID probe runs, with no global mocks.
				const owner = Bun.spawn([process.execPath, "-e", "process.exit(0)"], {
					stdout: "ignore",
					stderr: "ignore",
				});
				expect(await owner.exited).toBe(0);
				const scope: SharedTargetScope = {
					projectDir: runtimeDir,
					runtimeDir,
					daemonName: "omp.browser.relay-test",
				};
				const targetId = `PAGE${ANON}.9`;
				const ownershipFile = path.join(runtimeDir, `${scope.daemonName}.targets`, `${owner.pid}.json`);
				// Far outside the production 15-second grace window; no sleeps or clock mutation.
				await Bun.write(ownershipFile, JSON.stringify({ pid: owner.pid, updatedAt: 0, targets: [targetId] }));
				const browser = {
					target: () => {
						throw new Error("Relay cleanup must not use the nonexistent browser target");
					},
				} as unknown as Browser;
				await run({
					bridge: relay.bridge,
					ownershipFile,
					targetId,
					reap: () =>
						reapOrphanSharedTargets(browser, scope, id =>
							closeRelayOwnedTarget(`ws://127.0.0.1:${relay.port}/cdp`, id),
						),
				});
			} finally {
				relay.stop();
				await fs.rm(runtimeDir, { recursive: true, force: true });
			}
		}

		/** Fake extension that really removes the advertised target if the bridge asks it to. */
		class RemovingExtSocket extends FakeExtSocket {
			constructor(readonly bridge: RelayBridge) {
				super();
			}
			override send(text: string): void {
				super.send(text);
				const message = JSON.parse(text) as RelayToExtMessage;
				if (message.t !== "rpc" || message.op !== "removeTab") return;
				this.bridge.extMessage(this, JSON.stringify({ t: "tabRemoved", tabId: message.tabId }));
				ack(this.bridge, this, "removeTab");
			}
		}

		it("consumes a dead owner's stale record without closing a user tab that reuses its target id after reconnect", async () => {
			await withOrphanRecord(async ({ bridge, ownershipFile, targetId, reap }) => {
				const previous = new FakeExtSocket();
				helloWithOwned(bridge, previous, [tab({ tabId: 9 })], [9]);
				expect(bridge.listTargets().map(target => target.id)).toEqual([targetId]);
				bridge.extClosed(previous);

				// Synthetic forced collision: emulate a browser restart with the SAME instance/tab id.
				// This proves the composed protocol/registry guard, not real Chrome restart behavior.
				const restarted = new RemovingExtSocket(bridge);
				const userTab = tab({ tabId: 9, title: "User tab after restart", url: "https://user.example/" });
				helloWithOwned(bridge, restarted, [userTab], []);
				expect(bridge.listTargets()).toEqual([
					{
						id: targetId,
						type: "page",
						title: userTab.title,
						url: userTab.url,
						active: "false",
						discarded: "false",
					},
				]);

				// The count is resolved registry entries, including stale records, not tabs closed.
				expect(await reap()).toBe(1);
				expect(previous.rpcs("removeTab")).toEqual([]);
				expect(restarted.rpcs("removeTab")).toEqual([]);
				expect(bridge.listTargets()).toEqual([
					{
						id: targetId,
						type: "page",
						title: userTab.title,
						url: userTab.url,
						active: "false",
						discarded: "false",
					},
				]);
				expect(await Bun.file(ownershipFile).exists()).toBe(false);
			});
		});

		it("closes a current owned unclaimed tab through the same reaper and consumes its dead owner's record", async () => {
			await withOrphanRecord(async ({ bridge, ownershipFile, targetId, reap }) => {
				const extension = new RemovingExtSocket(bridge);
				helloWithOwned(bridge, extension, [tab({ tabId: 9 })], [9]);
				expect(bridge.listTargets().map(target => target.id)).toEqual([targetId]);

				expect(await reap()).toBe(1);
				expect(extension.rpcs("removeTab").map(rpc => rpc.tabId)).toEqual([9]);
				expect(bridge.listTargets()).toEqual([]);
				expect(await Bun.file(ownershipFile).exists()).toBe(false);
			});
		});
	});
});

describe("RelayBridge auto-attach gating", () => {
	function destroyedIds(cdp: FakeCdpSocket): string[] {
		const ids: string[] = [];
		for (const m of cdp.messages) {
			if (m.method !== "Target.targetDestroyed") continue;
			const params = m.params;
			if (params && typeof params === "object" && "targetId" in params && typeof params.targetId === "string") {
				ids.push(params.targetId);
			}
		}
		return ids;
	}

	function attachedIds(cdp: FakeCdpSocket): string[] {
		const ids: string[] = [];
		for (const m of cdp.messages) {
			if (m.method !== "Target.attachedToTarget") continue;
			const params = m.params;
			if (!(params && typeof params === "object" && "targetInfo" in params)) continue;
			const info = params.targetInfo;
			if (info && typeof info === "object" && "targetId" in info && typeof info.targetId === "string") {
				ids.push(info.targetId);
			}
		}
		return ids;
	}

	it("hides tabs from legacy extensions while allowing supported browsers through the relay", () => {
		const bridge = new RelayBridge();
		const legacy = new FakeExtSocket();
		bridge.extConnected(legacy);
		bridge.extMessage(
			legacy,
			JSON.stringify({
				t: "hello",
				userAgent: "test",
				browserVersion: "Chrome/150.0.0.0",
				tabs: [tab({ tabId: 1 })],
				attachedTabIds: [],
			}),
		);
		const supported = new FakeExtSocket();
		connectInstance(bridge, supported, "supported", [tab({ tabId: 2 })]);

		expect(bridge.listTargets().map(target => target.id)).toEqual([`PAGE${instanceCode("supported")}.2`]);
		expect(bridge.versionInfo("ws://relay/cdp").ompExtensionDiscardedTabsProtocol).toBe("1");
	});

	it("eagerly attaches live tabs and retracts discarded tabs", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1, discarded: true }), tab({ tabId: 2 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		bridge.cdpMessage(
			connId,
			JSON.stringify({
				id: ++msgSeq,
				method: "Target.setAutoAttach",
				params: { autoAttach: true, flatten: true, waitForDebuggerOnStart: true },
			}),
		);
		ack(bridge, ext, "attach");
		await flush();

		expect(ext.rpcs("attach").map(r => r.tabId)).toEqual([2]);
		const attached = attachedIds(cdp);
		expect(attached).toContain(`TAB${ANON}.2`);
		expect(attached).not.toContain(`TAB${ANON}.1`);
		// The discarded tab was announced by setDiscoverTargets. Retract it
		// so Puppeteer's connect() can finish.
		expect(destroyedIds(cdp)).toContain(`PAGE${ANON}.1`);
	});

	it("announces revived tabs and retracts discarded tabs", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1, discarded: true }), tab({ tabId: 2 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		ack(bridge, ext, "attach");
		await flush();

		// Chrome reloads the discarded tab when the user activates it.
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: false }) }));
		ack(bridge, ext, "attach");
		await flush();
		expect(attachedIds(cdp)).toContain(`TAB${ANON}.1`);

		// A previously attached tab becomes discarded.
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 2, discarded: true }) }));
		await flush();
		expect(destroyedIds(cdp)).toContain(`PAGE${ANON}.2`);
		expect(ext.rpcs("detach").map(r => r.tabId)).toContain(2);
		ack(bridge, ext, "detach");
	});

	it("does not reattach an initially discovered tab discarded during attach", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));
		ack(bridge, ext, "attach");
		await flush();
		expect(destroyedIds(cdp)).toContain(`PAGE${ANON}.1`);
		expect(attachedIds(cdp)).not.toContain(`TAB${ANON}.1`);
		expect(ext.rpcs("detach").map(r => r.tabId)).toEqual([1]);
	});

	it("does not reattach a newly announced tab discarded during attach", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, []);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		await flush();
		bridge.extMessage(ext, JSON.stringify({ t: "tabCreated", tab: tab({ tabId: 1 }) }));
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));
		ack(bridge, ext, "attach");
		await flush();
		expect(destroyedIds(cdp)).toContain(`PAGE${ANON}.1`);
		expect(attachedIds(cdp)).not.toContain(`TAB${ANON}.1`);
		expect(ext.rpcs("detach").map(r => r.tabId)).toEqual([1]);
	});

	it("releases auto-attach promptly and retries after an in-flight attach fails on discard", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		const setAutoAttachId = ++msgSeq;
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: setAutoAttachId, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		expect(ext.pending("attach")).toHaveLength(1);

		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));
		try {
			await flush();
			expect(cdp.messages.some(message => message.id === setAutoAttachId && "result" in message)).toBe(true);
		} finally {
			nack(bridge, ext, "attach", "discarded tab");
			await flush();
		}

		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1 }) }));
		await flush();
		ack(bridge, ext, "attach");
		await flush();
		expect(bridge.listTargets().map(target => target.id)).toContain(`PAGE${ANON}.1`);
		expect(attachedIds(cdp)).toContain(`TAB${ANON}.1`);
	});

	it("rejects stale explicit attachment requests for discarded targets without an extension RPC", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		await flush();
		bridge.extMessage(ext, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));
		const attachId = ++msgSeq;
		bridge.cdpMessage(
			connId,
			JSON.stringify({
				id: attachId,
				method: "Target.attachToTarget",
				params: { targetId: `PAGE${ANON}.1`, flatten: true },
			}),
		);
		await flush();
		const reply = cdp.messages.find(message => message.id === attachId);
		expect(reply && "error" in reply).toBe(true);
		expect(ext.rpcs("attach")).toHaveLength(0);
	});

	it("reannounces a held tab on revival without attaching it while discarded", async () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [tab({ tabId: 1 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		ack(bridge, ext, "attach");
		await flush();
		expect(attachedIds(cdp)).toContain(`TAB${ANON}.1`);

		const replacement = new FakeExtSocket();
		connect(bridge, replacement, [tab({ tabId: 1, discarded: true })]);
		const discardedAttempts = replacement.rpcs("attach").length;
		nack(bridge, replacement, "attach");
		await flush();

		bridge.extMessage(replacement, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1 }) }));
		ack(bridge, replacement, "attach");
		await flush();

		expect(discardedAttempts).toBe(0);
		expect(bridge.listTargets().map(target => target.id)).toContain(`PAGE${ANON}.1`);
		expect(replacement.rpcs("attach").map(rpc => rpc.tabId)).toEqual([1]);
		expect(attachedIds(cdp).filter(id => id === `TAB${ANON}.1`)).toHaveLength(2);
	});
	it("clears cancelled attach state when a discarded extension reconnects", async () => {
		const bridge = new RelayBridge();
		const firstExtension = new FakeExtSocket();
		connect(bridge, firstExtension, [tab({ tabId: 1 })]);
		const cdp = new FakeCdpSocket();
		const connId = bridge.cdpConnected(cdp);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setDiscoverTargets", params: { discover: true } }),
		);
		bridge.cdpMessage(
			connId,
			JSON.stringify({ id: ++msgSeq, method: "Target.setAutoAttach", params: { autoAttach: true } }),
		);
		await flush();
		expect(firstExtension.pending("attach")).toHaveLength(1);
		bridge.extMessage(firstExtension, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));

		const replacement = new FakeExtSocket();
		connect(bridge, replacement, [tab({ tabId: 1, discarded: true })]);
		await flush();
		expect(replacement.rpcs("attach")).toHaveLength(0);

		bridge.extMessage(replacement, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1 }) }));
		await flush();
		expect(replacement.pending("attach")).toHaveLength(1);
		bridge.extMessage(replacement, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1, discarded: true }) }));
		nack(bridge, replacement, "attach", "discarded tab again");
		await flush();

		bridge.extMessage(replacement, JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 1 }) }));
		await flush();
		ack(bridge, replacement, "attach");
		await flush();
		expect(attachedIds(cdp)).toContain(`TAB${ANON}.1`);
	});
});

describe("RelayBridge active tab metadata", () => {
	it("keeps only the newly activated tab active in its window", () => {
		const bridge = new RelayBridge();
		const ext = new FakeExtSocket();
		connect(bridge, ext, [
			tab({ tabId: 1, title: "First", active: true }),
			tab({ tabId: 2, title: "Second" }),
			tab({ tabId: 3, title: "Other window", active: true, windowId: 2 }),
		]);
		bridge.extMessage(
			ext,
			JSON.stringify({ t: "tabUpdated", tab: tab({ tabId: 2, title: "Second", active: true }) }),
		);
		expect(bridge.listTargets().map(t => [t.title, t.active])).toEqual([
			["First", "false"],
			["Second", "true"],
			["Other window", "true"],
		]);
	});
});

