		const picked = await pickElectronTarget(browser, {
			relayJson,
			matcher: "cart",
		});

		expect(picked).toBe(made.page);
		expect((target12 as unknown as { page: { mock: { calls: unknown[] } } }).page.mock.calls.length).toBe(0);
